  shimmerL; shimmerR;

  // Early tap config
  earlyTapTimes = [0.025, 0.035, 0.045, 0.055, 0.065, 0.075, 0.085, 0.095];
  earlyTapGains = [0.9, 0.75, 0.6, 0.5, 0.4, 0.3, 0.25, 0.2];
